INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (1, 'Chief Risk Officer', 'Owns the enterprise risk framework and reports to the board risk committee.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (2, 'Risk Manager', 'Runs RCSA cycles with the departments and approves risk assessments.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (3, 'Risk Analyst', 'Prepares assessments, maintains the register and tracks actions.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (4, 'Chief Information Officer', 'Accountable for the ERP, IT systems and information security.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (5, 'Chief Financial Officer', 'Accountable for finance, treasury and financial reporting.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (6, 'Chief Operating Officer', 'Accountable for manufacturing, quality and health & safety.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (7, 'Chief Compliance Officer', 'Accountable for legal and regulatory compliance.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (8, 'Internal Auditor', 'Provides independent assurance over controls.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (9, 'Head of Supply Chain', 'Accountable for procurement, suppliers, inventory and logistics.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (10, 'Chief Human Resources Officer', 'Accountable for people, payroll and workplace policies.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (11, 'Head of Sales', 'Accountable for customers, orders and revenue.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (12, 'Head of R&D', 'Accountable for product development and launches.');
INSERT INTO PER_MST_DESIGNATION (UUID, DESIGNATION, DESIGNATION_DESCRIPTION) VALUES (13, 'Head of Customer Service', 'Accountable for customer support and complaints.');
